INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1511463-mgt398', 'stk-rami_ali_ce_1990', 'MGT 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\n1- يتوفر فرصة تدريب تعاوني بمسمى | Marketing Intern\n\nالمؤهلات العلمية : تخصص ادارة او تسويق( Management or Marketing)\n\nالمهارات الشخصية : شخص منظم جدا وتماما، مهارات تواصل\n\nمعلومات : اذا اثبت الشخص نفسه سيكون هناك فرصة لعقد يتجدد بشكل سنوي\n\nالمكان : الشرقية او الرياض\n\nالجنس | ذكر او انثى\n\n2- فرصة وظيفة بمسمى | Marketing Coordinator\n\nالمؤهلات العلمية : تخصص ادارة او تسويق( Management or Marketing) يفضل حديث تخرج\n\nالمهارات الشخصية : شخص منظم جدا وتماما، مهارات تواصل\n\nمعلومات : دوام مريح مافي تدقيق عالحضور والانصراف\n\nالمكان : الشرقية او الرياض\n\nالجنس | ذكر او انثى\n\nالرجاء التواصل عالخاص لاي استفسار او ارسال السيرة الذاتية على ali.r.g.mohammed@gmail.com\n\nودمتم بود يا شباب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181661/1", "user": "Rami_Ali_CE_1990", "ts": 1561284451000, "tid": 181661, "pn": 1}}', 1561284451000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p67902-mgt398', 'stk-thecollector', 'MGT 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته…\n\nفي العموم متطلبات الكوأب وحدة، لكن في تغيرات طفيفة من تخصص لآخر…\n\nانقل لك المعلومات العامة من موقع عمادة شؤون الطلاب\nhttp://www.kfupm.edu.sa/studentaffairs/Ara/EduServices/Coop/\n\nالمتطلبات الاكاديمية للبرنامج\nلكي يصبح الطالب مرشحاً لتسجيل البرنامج التعاوني فإن عليه إستيفاء الشروط التالية .\n\nأن يكون قد أكمل أكثر من 85 وحدة دراسية في برنامج الشهادة العلمية المسجل فيها ( بما في ذلك الوحدات الدراسية التي من المتوقع أن يكملها في نهاية الفصل الدراسي الذي يسبق فترة البرنامج التعاوني .\nأن لا يقل معدل التخصص عن (2,00) .\nأن لا يكون موقوفاً عن الدراسة في الجامعة.\nأن يكون مستوفياً لمتطلبات القسم أو الكلية التي يتبع لهما.\nملاحظة : يجب على الطالب أن يكمل فترة تدريب البرنامج التعاوني قبل آخر فصل دراسي له في الجامعة ولا يعفى من ذلك إلا من لديه مبررات يقرها قسم التخصص قبل الموافقة عليها من قبل وكيل الجامعة للشؤون الأكاديمية.\nخطوات التسجيل\n#يبدأ التسجيل للبرنامج التعاوني عادة في بداية الأسبوع الثالث من كل فصل دراسي ويستمر لمدة خمسة أسابيع ، وفيما يلي خطوات التسجيل :\n#يتوجه الطالب المرشح إلى منسق البرنامج التعاوني بقسم تخصص الطالب لتعبئة نموذج التسجيل .\n#يتولى منسق البرنامج التعاوني إرسال نماذج التسجيل إلى إدارة البرنامج التعاوني بعمادة شؤون الطلاب .\n#تتولى إدارة البرنامج التعاوني إكمال باقي إجراءات التسجيل بالتنسيق مع مسجل الجامعة\n\nتعيين جهة التدريب\nتتولى إدارة البرنامج التعاوني بعماده شؤون الطلاب مهمة التنسيق مع الشركات و المؤسسات داخل المملكة و خارجها بهدف إيجاد فرص تدريبية للمرشحين للبرنامج التعاوني0 حيث تقوم الإدارة بمراسلة الجهات المعنية و دعوتها قبل فترة كافية لتقديم الفرص المتاحة لديها و أماكنها و المميزات التي تمنحها هذه الجهات للمتدربين. بعد ذلك، يتم اتباع الخطوات التالية لتعيين الطلاب في جهات التدريب :\n\n1 - إعلان جميع الفرص الواردة إلى الإدارة لجميع المرشحين للبرنامج حسب توالي وصولها0\n\n2 - إعلان المواعيد المحددة للطلاب لاختيار جهات التدريب0\n\n3 - يختار الطالب الجهات التي يود قضاء التدريب فيها على الترتيب الذي يرغبه بتعبئة النموذج المخصص لاختيار الجهات، مع إرفاق نسخة من السيرة الذاتية للطالب، وسجل الدرجات ( حسب طلب الجهة ) 0\n\n4 - مراسلة الجهات على الترتيب الذي اختاره الطالب و من ثم تعيينه في الجهة التي توافق على تدريبه0 وفي حالة تكليف الجهة لإدارة البرنامج التعاوني لاختيار الطلاب فتتم المفاضلة بين الطلاب حسب شروط الجهة والمعايير المعلنة في النموذج0\n\n5 - يراجع الطالب إدارة البرنامج التعاوني لاستلام خطاب التوجيه إلى جهة التدريب وبقية النماذج و المعلومات المطلوبة0\n\nيقوم أحياناً عدد من جهات التدريب بالمشاركة في اليوم المفتوح للتوظيف و يوم المهنة السنوي، أو زيارة الجامعة و أجراء اختبارات و مقابلات مع الطلاب المرشحين يتم على ضوئها اختيار من ترغب تلك الجهات في تدريبهم.\n\nو يسمح للطالب الذي يرغب في توفير فرصة تدريبية بنفسه الاتصال بجهة التدريب مباشرة بالتنسيق مع إدارة البرنامج التعاوني التي سوف تزوده بخطاب التعريف و المعلومات التي تطلبها جهة التدريب، شريطة أن يوافق القسم الأكاديمي بعد ذلك على هذه الجهة وطبيعة التدريب فيها.\n\nوفي جميع هذه الحالات فإن على الطالب مراجعة إدارة البرنامج التعاوني لإكمال الإجراءات الإدارية قبل مغادرة الجامعة للتدريب.\n\nنماذج التدريب التعاوني\nhttp://www.kfupm.edu.sa/studentaffairs/Ara/EduServices/Coop/coop_samples.htm\n\nولمزيد من المعلومات راجع الرابط الأول\n\nوفقك الله 🙂\n\nلك التحية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/co-op/44412/2", "user": "TheCollector", "ts": 1107180273000, "tid": 44412, "pn": 2}}', 1107180273000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p615998-mgt398', 'stk-user2316', 'MGT 398', 'info', '{"desc": "السلام عليكم\nصباحكم/مساؤكم ورد 🌹\n\nتعلن شركة جينيرال اليكتريك(GE) عن توفر فرصة لتطبيق البرنامج التعاوني(الكوأب) في دولة الامارات لطلاب الإدارة (MGT,Marketing,). التطبيق سوف يكون في مجال الموارد البشرية(HR)…\n\nفمن لديه رغبة التطبيق في هذا المجال.أرجو منه مراسلتي عن طريق الخاص…🙂\n\nقصي الضراب\nمنسق شركة جينيرال اليكتريك في الجامعة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/88882/1", "user": "user2316", "ts": 1274936167000, "tid": 88882, "pn": 1}}', 1274936167000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1462433-mgt398', 'stk-user8581', 'MGT 398', 'info', '{"desc": "فرص** كواب** ( تدريب تعاوني ) في شركة التكامل القابضة في الرياض لعدة تخصصات :\n\nالموارد البشرية HR\nإدارة نظم المعلومات MIS\nالإدارة MGT\nالتسويق MKT\n\n**رابط التقديم **\nJob – Takamol Recruitment\n\n- مدة التدريب بين 5 إلى 7 أشهر-\n\nSummary:\nAt Takamol Holding, we are working with the Ministry of Labor and Social Development to achieve a significant and lasting impact on the labor market in the Kingdom. In line with this mission, we have been training co-op trainees over the past few years. Our Cooperative Training Program targets dynamic college seniors who have a passion to be part of the change which Takamol drives. After going through a careful selection process, the selected participants will join the 5-7 month program in which they work arm-to-arm with top professionals, supporting some of the nation’s most significant projects.\n\nRequirements:\n\nHigh English Proficiency\n\nA Minimum GPA of (3/4) or (4/5)\nParticipation in Volunteering and Extracurricular Activities is Preferred\nProven Leadership Skills\nAn Expected Bachelor’s Degree in (Business Administration, HR, Project Management, MIS, Innovation, or Marketing\nLocation:\n\nRiyadh, Saudi Arabia", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/162-163-171/174980/18", "user": "user8581", "ts": 1479293370000, "tid": 174980, "pn": 18}}', 1479293370000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
